public void whileSelectPlusDoInsertVSInsertRecordSet()
{
    AIBBookTable bookTable;
    AIBBookTableAlternate bookTableAlt;
    int recordsInsertedDoInsert;
    while select booktable
    {
        bookTableAlt.id = booktable.id;
        bookTableAlt.author = booktable.author;
        bookTableAlt.genre = booktable.genre;
        bookTableAlt.name = booktable.name;
        bookTableAlt.doInsert();
        recordsInsertedDoInsert++;
    }
    bookTableAlt.skipDataMethods(true);
    insert_recordset bookTableAlt (Id, Author, Genre, Name)
        select Id, Author, Genre, Name from bookTable;

    info(strFmt("%1 records inserted using DoInsert, %2 records inserted using insertRecordSet", recordsInsertedDoInsert, bookTableAlt.RowCount()));

}

public void whileSelectUpdateVSUpdateRecordSet()
{
    AIBAuthorTable authorTable;

    ttsbegin;
    while select forupdate authorTable
        where authorTable.IsDead == NoYes::No
        && authorTable.DeathDate > dateNull()
    {
        authorTable.DeathDate = dateNull();
        authorTable.update();
    }
    ttscommit;

    ttsbegin;
    update_recordset authorTable
        setting DeathDate = dateNull()
        where authorTable.IsDead == NoYes::No
        && authorTable.DeathDate > dateNull();
    ttscommit;
}

public void shileSelectPlusDeleteVSDelete_From()
{
    AIBAuthorTable authorTable;
    AIBBookTable bookTable;

    ttsbegin;
    while select forupdate bookTable
        exists join authorTable
        where authorTable.RecId == bookTable.Author
        && authorTable.IsDead == NoYes::Yes
    {
        bookTable.delete();
    }
    ttscommit;

    ttsbegin;
    delete_from bookTable
        exists join authorTable
        where authorTable.RecId == bookTable.Author
        && authorTable.IsDead == NoYes::Yes;
    ttscommit;
}

public void whileSelectButInsertInSet()
{
    RecordInsertList recordInsertList = new RecordInsertList(tableNum(AIBBookTableAlternate));
    AIBBookTable bookTable;

    while select bookTable
    {
        AIBBookTableAlternate altBookTable;
        Name bookName =  (bookTable.Genre == AIBGenreEnum::Fantasy) ? str2Capital(bookTable.Name) : strLwr(bookTable.Name);
        altBookTable.Author = bookTable.Author;
        altBookTable.Name = bookTable.Name;
        altBookTable.Genre = bookTable.Genre;
        altBookTable.Id = bookTable.Id;

        recordInsertList.add(altBookTable);
    }
}
